insert into public.medical_terms(term,title,meaning,questions,approved,is_demo) values('ЗРР','Задержка речевого развития','Так называют ситуацию, когда речь развивается медленнее ожидаемого. Это описание требует профессионального уточнения и само по себе не объясняет причину.',array['Как это проявляется в нашей ситуации?','Что и как мы можем наблюдать дома?','Когда стоит обсудить план повторно?']::text[],false,true) on conflict do nothing;
insert into public.medical_terms(term,title,meaning,questions,approved,is_demo) values('ПМПК','Психолого-медико-педагогическая консультация','Помогает оценить образовательные потребности и обсудить доступную поддержку. Порядок обращения и бесплатные услуги уточняйте в местной ПМПК.',array['Как это проявляется в нашей ситуации?','Что и как мы можем наблюдать дома?','Когда стоит обсудить план повторно?']::text[],false,true) on conflict do nothing;
insert into public.medical_terms(term,title,meaning,questions,approved,is_demo) values('Логопед','Специалист по речи и коммуникации','Оценивает особенности речи и общения, обсуждает с семьёй задачи и способы поддержки.',array['Как это проявляется в нашей ситуации?','Что и как мы можем наблюдать дома?','Когда стоит обсудить план повторно?']::text[],false,true) on conflict do nothing;
insert into public.medical_terms(term,title,meaning,questions,approved,is_demo) values('Дефектолог','Специальный педагог','Помогает подобрать способы обучения с учётом особенностей развития и образовательных потребностей.',array['Как это проявляется в нашей ситуации?','Что и как мы можем наблюдать дома?','Когда стоит обсудить план повторно?']::text[],false,true) on conflict do nothing;
insert into public.medical_terms(term,title,meaning,questions,approved,is_demo) values('Сурдолог','Специалист по слуху','Оценивает слух. Обсудить проверку слуха может быть полезно при вопросах о развитии речи.',array['Как это проявляется в нашей ситуации?','Что и как мы можем наблюдать дома?','Когда стоит обсудить план повторно?']::text[],false,true) on conflict do nothing;
insert into public.medical_terms(term,title,meaning,questions,approved,is_demo) values('Сенсорные особенности','Восприятие ощущений','Ребёнок может иначе реагировать на звук, свет, прикосновения или движение. Поддержку подбирают индивидуально.',array['Как это проявляется в нашей ситуации?','Что и как мы можем наблюдать дома?','Когда стоит обсудить план повторно?']::text[],false,true) on conflict do nothing;
insert into public.medical_terms(term,title,meaning,questions,approved,is_demo) values('Коммуникация','Как мы понимаем друг друга','Обмен просьбами, чувствами и информацией через речь, жесты, взгляд, картинки и другие доступные способы.',array['Как это проявляется в нашей ситуации?','Что и как мы можем наблюдать дома?','Когда стоит обсудить план повторно?']::text[],false,true) on conflict do nothing;
insert into public.medical_terms(term,title,meaning,questions,approved,is_demo) values('Альтернативная коммуникация','Дополнительные способы общения','Жесты, карточки и устройства могут помогать выражать мысли и потребности. Подход выбирают вместе со специалистом.',array['Как это проявляется в нашей ситуации?','Что и как мы можем наблюдать дома?','Когда стоит обсудить план повторно?']::text[],false,true) on conflict do nothing;
insert into public.medical_terms(term,title,meaning,questions,approved,is_demo) values('Моторика','Навыки движения','Крупная моторика — движения тела, мелкая — точные движения кистей и пальцев.',array['Как это проявляется в нашей ситуации?','Что и как мы можем наблюдать дома?','Когда стоит обсудить план повторно?']::text[],false,true) on conflict do nothing;
